void main() => runApp(const NibrasDocsApp());

class DocItem {
  final String id;
  String title, content, category, tags;
  bool favorite, pinned, deleted;
  DateTime created, modified;
  DocItem({required this.id, required this.title, this.content='', this.category='Personal', this.tags='', this.favorite=false, this.pinned=false, this.deleted=false, DateTime? created, DateTime? modified})
      : created=created ?? DateTime.now(), modified=modified ?? DateTime.now();
  Map<String,dynamic> toJson()=>{'id':id,'title':title,'content':content,'category':category,'tags':tags,'favorite':favorite,'pinned':pinned,'deleted':deleted,'created':created.toIso8601String(),'modified':modified.toIso8601String()};
  factory DocItem.fromJson(Map<String,dynamic> j)=>DocItem(id:j['id'],title:j['title'],content:j['content']??'',category:j['category']??'Personal',tags:j['tags']??'',favorite:j['favorite']??false,pinned:j['pinned']??false,deleted:j['deleted']??false,created:DateTime.tryParse(j['created']??''),modified:DateTime.tryParse(j['modified']??''));
}

class NibrasDocsApp extends StatefulWidget { const NibrasDocsApp({super.key}); @override State<NibrasDocsApp> createState()=>_AppState(); }
class _AppState extends State<NibrasDocsApp>{ bool dark=true; void toggle()=>setState(()=>dark=!dark);
  @override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Nibras Docs',themeMode:dark?ThemeMode.dark:ThemeMode.light,
    darkTheme:_theme(Brightness.dark),theme:_theme(Brightness.light),home:Splash(onTheme:toggle));
  ThemeData _theme(Brightness b){final dark=b==Brightness.dark; return ThemeData(brightness:b,useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff14c9ff),brightness:b),scaffoldBackgroundColor:dark?const Color(0xff061226):const Color(0xfff3f7ff),fontFamily:'sans-serif',cardTheme:CardThemeData(color:dark?const Color(0xff0d203d):Colors.white,elevation:0,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(22))));}
}

class Splash extends StatefulWidget {final VoidCallback onTheme; const Splash({super.key,required this.onTheme}); @override State<Splash> createState()=>_SplashState();}
class _SplashState extends State<Splash>{ @override void initState(){super.initState(); Future.delayed(const Duration(milliseconds:1500),(){if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>Home(onTheme:widget.onTheme)));});}
 @override Widget build(BuildContext c)=>Scaffold(body:Container(decoration:const BoxDecoration(gradient:RadialGradient(center:Alignment.topRight,radius:1.3,colors:[Color(0xff123c7a),Color(0xff061226),Color(0xff020816)])),child:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Image.asset('assets/images/nibras_icon.png',width:150,height:150),const SizedBox(height:18),const Text('Nibras Docs',style:TextStyle(fontSize:38,fontWeight:FontWeight.w800)),const Text('CREATE  •  EDIT  •  ORGANIZE',style:TextStyle(color:Color(0xff6addff),letterSpacing:2)),const SizedBox(height:38),const CircularProgressIndicator(),const SizedBox(height:18),const Text('Preparing your workspace...',style:TextStyle(color:Colors.white60))]))));}

class Home extends StatefulWidget {final VoidCallback onTheme; const Home({super.key,required this.onTheme}); @override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{ final docs=<DocItem>[]; final folders=<String>['Hamısı','Personal','Work','Study','Archive']; final store=LocalStore(); int tab=0; String q=''; String activeFolder='Hamısı'; bool loaded=false;
 @override void initState(){super.initState();_load();}
 Future<void> _load()async{final data=await store.load();docs.addAll(((data['documents']??[]) as List).map((e)=>DocItem.fromJson(Map<String,dynamic>.from(e))));for(final f in ((data['folders']??[]) as List)){final name=f.toString();if(name.isNotEmpty&&!folders.contains(name))folders.add(name);}if(mounted)setState(()=>loaded=true);}
 Future<void> _save()async{await store.save({'documents':docs.map((e)=>e.toJson()).toList(),'folders':folders.where((f)=>f!='Hamısı').toList()});if(mounted)setState((){});}
 List<DocItem> get shown{var x=docs.where((d)=>tab==2?d.deleted:!d.deleted).where((d)=>tab!=1||d.favorite).where((d)=>activeFolder=='Hamısı'||d.category==activeFolder).where((d)=>d.title.toLowerCase().contains(q.toLowerCase())||d.content.toLowerCase().contains(q.toLowerCase())||d.tags.toLowerCase().contains(q.toLowerCase())).toList();x.sort((a,b){if(a.pinned!=b.pinned)return a.pinned?-1:1;return b.modified.compareTo(a.modified);});return x;}
 Future<void> edit([DocItem? d])async{final item=d??DocItem(id:DateTime.now().microsecondsSinceEpoch.toString(),title:'Yeni sənəd',category:activeFolder=='Hamısı'?'Personal':activeFolder);await Navigator.push(context,MaterialPageRoute(builder:(_)=>Editor(doc:item,folders:folders.where((f)=>f!='Hamısı').toList(),onSave:(x){if(d==null)docs.add(x);_save();})));}
 @override Widget build(BuildContext c){if(!loaded)return const Scaffold(body:Center(child:CircularProgressIndicator()));return Scaffold(appBar:AppBar(title:Row(children:[Image.asset('assets/images/nibras_icon.png',width:40,height:40),const SizedBox(width:10),const Text('Nibras Docs',style:TextStyle(fontWeight:FontWeight.w800))]),actions:[IconButton(tooltip:'Backup yarat',onPressed:()async{final f=await store.backup({'documents':docs.map((e)=>e.toJson()).toList()});if(mounted){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Backup yaradıldı: ${f.path}')));}},icon:const Icon(Icons.backup_outlined)),IconButton(onPressed:widget.onTheme,icon:const Icon(Icons.contrast)),PopupMenuButton(itemBuilder:(_)=>[const PopupMenuItem(value:'about',child:Text('Nibras Code haqqında'))],onSelected:(_)=>showAboutDialog(context:context,applicationName:'Nibras Docs',applicationVersion:'1.0.0'))]),
 body:Column(children:[_dashboard(),_folderBar(),Padding(padding:const EdgeInsets.fromLTRB(16,8,16,12),child:TextField(onChanged:(v)=>setState(()=>q=v),decoration:InputDecoration(prefixIcon:const Icon(Icons.search),hintText:'Sənədlərdə axtar...',filled:true,border:OutlineInputBorder(borderRadius:BorderRadius.circular(18),borderSide:BorderSide.none)))),
 Expanded(child:shown.isEmpty?_empty():ListView.builder(padding:const EdgeInsets.fromLTRB(16,0,16,100),itemCount:shown.length,itemBuilder:(_,i)=>_card(shown[i])))]),
 floatingActionButton:tab==2?null:FloatingActionButton.extended(onPressed:()=>edit(),icon:const Icon(Icons.add),label:const Text('Yeni sənəd')),
 bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const [NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home),label:'Ana səhifə'),NavigationDestination(icon:Icon(Icons.star_outline),selectedIcon:Icon(Icons.star),label:'Seçilmişlər'),NavigationDestination(icon:Icon(Icons.delete_outline),selectedIcon:Icon(Icons.delete),label:'Səbət')]));}

 Future<void> _newFolder()async{final c=TextEditingController();final name=await showDialog<String>(context:context,builder:(_)=>AlertDialog(title:const Text('Yeni qovluq'),content:TextField(controller:c,autofocus:true,decoration:const InputDecoration(hintText:'Qovluq adı')),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Ləğv et')),FilledButton(onPressed:()=>Navigator.pop(context,c.text.trim()),child:const Text('Yarat'))]));if(name!=null&&name.isNotEmpty&&!folders.contains(name)){folders.add(name);activeFolder=name;await _save();}}
 Future<void> _manageFolder(String old)async{final action=await showModalBottomSheet<String>(context:context,builder:(_)=>SafeArea(child:Wrap(children:[ListTile(leading:const Icon(Icons.drive_file_rename_outline),title:const Text('Adını dəyiş'),onTap:()=>Navigator.pop(context,'rename')),ListTile(leading:const Icon(Icons.delete_outline),title:const Text('Qovluğu sil'),subtitle:const Text('Sənədlər Personal qovluğuna köçürüləcək'),onTap:()=>Navigator.pop(context,'delete'))])));if(action=='rename'){final c=TextEditingController(text:old);final name=await showDialog<String>(context:context,builder:(_)=>AlertDialog(title:const Text('Qovluğun adını dəyiş'),content:TextField(controller:c,autofocus:true),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Ləğv et')),FilledButton(onPressed:()=>Navigator.pop(context,c.text.trim()),child:const Text('Saxla'))]));if(name!=null&&name.isNotEmpty&&!folders.contains(name)){for(final d in docs.where((d)=>d.category==old)){d.category=name;}folders[folders.indexOf(old)]=name;if(activeFolder==old)activeFolder=name;await _save();}}else if(action=='delete'){for(final d in docs.where((d)=>d.category==old)){d.category='Personal';}folders.remove(old);if(activeFolder==old)activeFolder='Hamısı';await _save();}}
 Widget _folderBar()=>SizedBox(height:54,child:ListView(scrollDirection:Axis.horizontal,padding:const EdgeInsets.symmetric(horizontal:12),children:[...folders.map((f)=>Padding(padding:const EdgeInsets.symmetric(horizontal:4),child:GestureDetector(onLongPress:f=='Hamısı'?null:()=>_manageFolder(f),child:ChoiceChip(label:Text(f),selected:activeFolder==f,onSelected:(_)=>setState(()=>activeFolder=f))))),Padding(padding:const EdgeInsets.symmetric(horizontal:4),child:ActionChip(avatar:const Icon(Icons.create_new_folder_outlined,size:18),label:const Text('Qovluq'),onPressed:_newFolder))]));
  Widget _dashboard()=>SizedBox(height:92,child:ListView(scrollDirection:Axis.horizontal,padding:const EdgeInsets.symmetric(horizontal:12),children:[_stat('Sənəd',docs.where((d)=>!d.deleted).length,Icons.description),_stat('Seçilmiş',docs.where((d)=>d.favorite&&!d.deleted).length,Icons.star),_stat('Pin',docs.where((d)=>d.pinned&&!d.deleted).length,Icons.push_pin),_stat('Səbət',docs.where((d)=>d.deleted).length,Icons.delete)]));
