 Widget _empty()=>Center(child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.description_outlined,size:72,color:Color(0xff22cfff)),const SizedBox(height:14),Text(tab==1?'Seçilmiş sənəd yoxdur':'İlk sənədini yarat',style:const TextStyle(fontSize:21,fontWeight:FontWeight.bold)),const SizedBox(height:6),const Text('Sadə, sürətli və oflayn iş sahəsi') ]));
 Widget _card(DocItem d)=>Card(child:ListTile(contentPadding:const EdgeInsets.all(14),leading:Container(width:52,height:52,decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xff176cff),Color(0xff1de1ff)]),borderRadius:BorderRadius.circular(15)),child:const Icon(Icons.description,color:Colors.white)),title:Row(children:[if(d.pinned)const Padding(padding:EdgeInsets.only(right:6),child:Icon(Icons.push_pin,size:16)),Expanded(child:Text(d.title,style:const TextStyle(fontWeight:FontWeight.w700)))]),subtitle:Text('${d.category} • ${d.content.trim().isEmpty?0:d.content.trim().split(RegExp(r"\\s+")).length} söz${d.tags.trim().isEmpty?'':' • ${d.tags}'}'),onTap:()=>edit(d),trailing:PopupMenuButton<String>(onSelected:(v)async{if(v=='fav')d.favorite=!d.favorite;if(v=='pin')d.pinned=!d.pinned;if(v=='pdf')await exportPdf(d);if(v=='epub'&&mounted)await Navigator.push(context,MaterialPageRoute(builder:(_)=>EpubPreviewScreen(doc:d)));if(v=='share')await exportDoc(d);if(v=='delete')d.deleted=true;if(v=='restore')d.deleted=false;if(v=='forever')docs.remove(d);_save();},itemBuilder:(_)=>[PopupMenuItem(value:'fav',child:Text(d.favorite?'Seçilmişdən çıxar':'Seçilmiş et')),PopupMenuItem(value:'pin',child:Text(d.pinned?'Sancağı çıxar':'Yuxarı sancaqla')),const PopupMenuItem(value:'pdf',child:Text('PDF ixrac et')),const PopupMenuItem(value:'epub',child:Text('EPUB önizləmə')),const PopupMenuItem(value:'share',child:Text('TXT paylaş')),if(!d.deleted)const PopupMenuItem(value:'delete',child:Text('Səbətə at')) else ...[const PopupMenuItem(value:'restore',child:Text('Bərpa et')),const PopupMenuItem(value:'forever',child:Text('Həmişəlik sil'))]])));
 Future<void> exportPdf(DocItem d)async{final o=await Navigator.push<Map<String,dynamic>>(context,MaterialPageRoute(builder:(_)=>const PdfOptionsScreen()));if(o==null)return;final file=await PdfExporter.create(title:d.title,content:d.content,category:d.category,tags:d.tags,family:o['font'],pageSize:o['size'],landscape:o['landscape']);await Share.shareXFiles([XFile(file.path)],text:'Nibras Docs PDF');}
 Future<void> exportDoc(DocItem d)async{final dir=await getTemporaryDirectory();final safe=d.title.replaceAll(RegExp(r'[^a-zA-Z0-9_-]'),'_');final f=File('${dir.path}/$safe.txt');await f.writeAsString('${d.title}\n\n${d.content}');await Share.shareXFiles([XFile(f.path)],text:'Nibras Docs');}
}

class Editor extends StatefulWidget{final DocItem doc;final List<String> folders;final ValueChanged<DocItem> onSave;const Editor({super.key,required this.doc,required this.folders,required this.onSave});@override State<Editor> createState()=>_EditorState();}
class _EditorState extends State<Editor>{late final TextEditingController title,body,tags;String category='Personal';
 @override void initState(){super.initState();title=TextEditingController(text:widget.doc.title);body=TextEditingController(text:widget.doc.content);tags=TextEditingController(text:widget.doc.tags);category=widget.doc.category;}
 void save(){widget.doc.title=title.text.trim().isEmpty?'Adsız sənəd':title.text.trim();widget.doc.content=body.text;widget.doc.tags=tags.text.trim();widget.doc.category=category;widget.doc.modified=DateTime.now();widget.onSave(widget.doc);Navigator.pop(context);}
