class _EpubPreviewState extends State<EpubPreviewScreen>{double fs=17;String mode='Sepia',device='Phone';@override Widget build(BuildContext c){final dark=mode=='Dark'||mode=='AMOLED';final bg=mode=='Sepia'?const Color(0xfffff3d2):(dark?Colors.black:Colors.white);final fg=dark?Colors.white:const Color(0xff392f24);final w=device=='Tablet'?520.0:device=='Kindle'?430.0:350.0;return Scaffold(appBar:AppBar(title:const Text('Nibras Docs • EPUB önizləmə')),body:Column(children:[Wrap(spacing:6,children:[...['Phone','Tablet','Kindle'].map((x)=>ChoiceChip(label:Text(x),selected:device==x,onSelected:(_)=>setState(()=>device=x))),...['Light','Sepia','Dark','AMOLED'].map((x)=>ChoiceChip(label:Text(x),selected:mode==x,onSelected:(_)=>setState(()=>mode=x)))]),Expanded(child:Center(child:Container(width:w,margin:const EdgeInsets.all(12),padding:const EdgeInsets.all(28),decoration:BoxDecoration(color:bg,borderRadius:BorderRadius.circular(18),boxShadow:const [BoxShadow(blurRadius:22,color:Colors.black38)]),child:SingleChildScrollView(child:DefaultTextStyle(style:TextStyle(color:fg,fontSize:fs,height:1.55,fontFamily:'serif'),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(widget.doc.title,style:TextStyle(fontSize:fs+10,fontWeight:FontWeight.bold)),const Divider(),Text(widget.doc.content.isEmpty?'Sənədə mətn əlavə edin.':widget.doc.content)])))))),Row(mainAxisAlignment:MainAxisAlignment.center,children:[IconButton(onPressed:()=>setState(()=>fs=(fs-1).clamp(12,28)),icon:const Icon(Icons.text_decrease)),Text('${fs.toInt()}'),IconButton(onPressed:()=>setState(()=>fs=(fs+1).clamp(12,28)),icon:const Icon(Icons.text_increase))]) ]));}}
